customer_id = #{customerId}, age = #{age}, gender = #{gender}, occupation = #{occupation}, annual_income = #{annualIncome}, has_social_insurance = #{hasSocialInsurance}, smoking_status = #{smokingStatus}, drinking_status = #{drinkingStatus}, family_medical_history = #{familyMedicalHistory}, personal_medical_history = #{personalMedicalHistory}, bmi = #{bmi}, blood_pressure = #{bloodPressure}, updated_at = #{updatedAt}, target = #{target}, score_v1 = #{scoreV1},
